export const templateTexts: { id: string; text: string }[] = [
  { id: "azul", text: "# azul.gamebuddy — draft tiles, fill a wall\n\n[game]\nname: Azul\nicon: azul\nplayers: 2-4\ntime: 40m\ntags: board, puzzle\nsource: https://boardgamegeek.com/boardgame/230802/azul\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Give every player a player board\n- Fill the round factory displays with four tiles each\n- Put the first player marker in the middle\n- Shuffle the bag\n\n[rules]\nTake tiles from a factory, place them on a pattern line, then score when the line completes.\n- A completed line scores its tile and every connected tile on the wall\n- Floor tiles cost points\n- The game ends when a player completes a row\n- Add end-of-game bonuses; the highest total wins\n\n[tool score]\nmode: ledger\nwin: highest\n" },
  { id: "bananagrams", text: "# bananagrams.gamebuddy — a shared pile of letters and one race\n\n[game]\nname: Bananagrams\nicon: bananagrams\nplayers: 2-8\ntime: 15m\ntags: words, realtime\nsource: https://en.wikipedia.org/wiki/Bananagrams\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Tip every tile face down in the middle and mix\n- Everyone takes their starting tiles\n- Agree who calls the start\n\n[rules]\nEveryone builds their own word grid at the same time from the shared pile.\n- Start together; take a new tile whenever you need one\n- When the pile is empty, call it and everyone checks their grid\n- A valid grid uses all your tiles in one connected crossword\n- First valid grid wins the round\n\n[tool bag pile]\nset: bananagrams\ndraw: 21\ntray: per-player\n\n[tool timer race]\nmode: countdown\nduration: 5m\nsound: buzzer\nwarn-at: 30s\n\n[tool words check]\nprofile: en\nmode: check\n\n[tool score]\nmode: rounds\nrounds: 3\nwin: highest\n" },
  { id: "boggle", text: "# boggle.gamebuddy — three minutes, then compare lists\n\n[game]\nname: Boggle\nplayers: 2-8\ntime: 15m\ntags: words, party\nicon: boggle\nsource: https://en.wikipedia.org/wiki/Boggle\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shake the letter dice and set the tray\n- Give everyone paper or use the score tool in rounds\n- Agree that only words of three letters or more count\n\n[rules]\nFind as many words as you can in the grid before the timer runs out.\n- Words must join neighbouring letters and may not reuse a die\n- Write your list, then read it out; crossed words score nothing\n- Short words are worth one point, longer words more\n- Highest score after the agreed number of rounds wins\n\n[tool timer round]\nmode: countdown\nduration: 3m\nsound: bell\nwarn-at: 20s\n\n[tool words check]\nprofile: en\nmode: filters\nlength: 3\n\n[tool score]\nmode: rounds\nrounds: 3\nwin: highest\n" },
  { id: "catan", text: "# catan.gamebuddy — victory points on the table, not on scrap paper\n\n[game]\nname: Catan\nplayers: 3-4\ntime: 90m\ntags: board, strategy\nicon: catan\nsource: https://www.catan.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle the hexes, ring the board with sea and place the desert\n- Shuffle the number tokens onto the hexes in order\n- Place one settlement and road per player in turn, then a second pair in reverse\n- Take the starting resources from the second settlement\n\n[rules]\nRace to 10 victory points. Settlements are 1 point, cities 2, longest road and largest army 2 each, and a few development cards add a point.\n- Roll for resources, trade, then build\n- The first player to reach 10 points on their own turn wins\n- Track the counts here; the totals follow the category points\n\n[tool score]\nmode: categories\ncategories: settlements=1, cities=2, longest-road=2, largest-army=2, cards=1\ntarget: 10\nwin: highest\n" },
  { id: "chess-blitz", text: "# chess-blitz.gamebuddy — two clocks, one increment\n\n[game]\nname: Chess / Blitz\nplayers: 2\ntime: 10-60m\ntags: board, duel\nicon: knight\nsource: https://www.fide.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Set up the board with the queen on her own colour\n- Agree on the time control, for example five minutes plus three seconds\n- Decide who plays white\n- Put the clocks where both players can reach them\n\n[rules]\nStandard chess. Checkmate wins; a flag fall loses on time.\n- White moves first, then players alternate\n- The clock only runs for the player to move\n- Tap the clock to hand the turn over; the increment is added\n- Resign, draw or checkmate ends the game\n\n[tool timer]\nmode: chess\nduration: 5m\nplayers: 2\nincrement: 3s\nsound: bell\nhaptic: short\n" },
  { id: "codenames", text: "# codenames.gamebuddy — a 5x5 board with a hidden key\n\n[game]\nname: Codenames\nplayers: 4-8\ntime: 20m\ntags: party, words\nicon: codenames\nsource: https://boardgamegeek.com/boardgame/178900/codenames\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Split into two teams and pick one spymaster per team\n- Generate a board; the spymaster peeks at the key privately\n- Place the red and blue agent cards if you have them, or track guesses here\n\n[rules]\nTwo spymasters know which words belong to which team; everyone else guesses.\n- A clue is one word and one number\n- Guess up to that many words; stop whenever you like\n- An innocent bystander ends your turn and the assassin loses the game\n- Clear all your team's words to win\n\n[tool words board]\nprofile: en\nmode: codenames\n\n[tool timer turn]\nmode: countdown\nduration: 2m\nwarn-at: 20s\nsound: bell\n\n[tool score]\nmode: simple\nwin: highest\n" },
  { id: "coup", text: "# coup.gamebuddy — two influences and a pile of coins\n\n[game]\nname: Coup\nicon: coup\nplayers: 2-6\ntime: 15m\ntags: party, bluffing\nsource: https://boardgamegeek.com/boardgame/131357/coup\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle the role deck and deal two face-down cards to each player\n- Give every player two coins\n- Put the rest of the deck face down as the court deck\n\n[rules]\nBluff your way to being the last player with influence.\n- Coins buy actions: income, foreign aid, coup and character powers\n- Anyone may challenge a claim; the loser loses an influence\n- Track coins as ledger entries and influences with the lives tool\n- The last player with a face-down card wins\n\n[tool lives]\nmode: players\nlives: 2\nmax: 2\nelimination: yes\n\n[tool score]\nmode: ledger\n\n[tool reveal]\nmode: roles\nroles: duke=3, assassin=3, captain=3, ambassador=3, contessa=3\ndescriptions: duke=Take three coins as tax, assassin=Pay three to assassinate, captain=Steal two coins, ambassador=Swap cards with the court, contessa=Blocks assassination\nauto-hide: 6\n" },
  { id: "decrypto", text: "# decrypto.gamebuddy — clues, interceptions and a two minute clock\n\n[game]\nname: Decrypto\nicon: decrypto\nplayers: 3-8\ntime: 30m\ntags: party, deduction\nsource: https://www.scorpionmasque.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Split into two teams and sit so each team shares a screen\n- Deal four keyword cards to each team\n- Give each team a code card and a pen\n- Put the interception tokens where both teams can reach them\n\n[rules]\nGive clues that point at your keywords without giving them away.\n- The clue giver writes a three number code, then says three clues\n- Their team guesses which keyword matches each number\n- The other team may try to intercept the code\n- Two interceptions or two miscommunications end the game; log tokens per team here\n\n[tool timer]\nmode: countdown\nduration: 2m\nsound: bell\nstart: manual\n\n[tool score]\nmode: ledger\nwin: lowest\n\n[tool reveal]\nmode: ballot\nballot: Did the other team intercept?\noptions: Intercepted, Missed\n" },
  { id: "dixit", text: "# dixit.gamebuddy — one sentence, six pictures, one guess\n\n[game]\nname: Dixit\nicon: dixit\nplayers: 3-6\ntime: 30m\ntags: party, cards\nsource: https://www.libellud.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Deal six cards to each player\n- Give every player a voting dial or tokens\n- Shuffle the rest of the deck as the draw pile\n\n[rules]\nThe storyteller says a sentence about a card, everyone else adds a card, then the table votes.\n- Score three points if your card is guessed\n- The storyteller scores if some but not all players guess their card\n- Everyone who votes for the storyteller's card scores too\n- First to 30 points wins\n\n[tool score]\nmode: simple\ntarget: 30\nwin: highest\n\n[tool reveal]\nmode: ballot\nballot: Was the storyteller found?\noptions: Found, Missed\n" },
  { id: "dnd-5e-combat", text: "# dnd-5e-combat.gamebuddy — initiative, hit points and dice macros\n\n[game]\nname: D&D 5e combat\nplayers: 3-7\ntime: varies\ntags: rpg, combat\nicon: d20\nsource: https://dnd.wizards.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Roll initiative for every combatant and write the order\n- Note each character's maximum hit points\n- Put the dice where everyone can reach them\n- Agree on how long a turn may take\n\n[rules]\nCombat runs in rounds. Each turn has movement, one action and possibly a bonus action.\n- Roll initiative once; highest goes first\n- Attack, cast or dash as your action\n- Track hit points and conditions here\n- The fight ends when one side is down or flees\n\n[tool turns]\nphases: Action, Bonus action, Move, End\ntimer: 1m\npass: no\nauto-start: no\n\n[tool lives]\nmode: players\nlives: 30\nmax: 60\nelimination: yes\n\n[tool dice]\nroll: 1d20\nmacros: attack=1d20+5, damage=2d6+3, save=1d20\n" },
  { id: "dominion", text: "# dominion.gamebuddy — deck building and victory cards\n\n[game]\nname: Dominion\nicon: dominion\nplayers: 2-4\ntime: 30m\ntags: card, deckbuilder\nsource: https://www.riograndegames.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Lay out ten kingdom cards plus the base treasures and victory cards\n- Give every player a starting deck: seven coppers and three estates\n- Shuffle and draw five cards\n- Put the trash pile in the middle\n\n[rules]\nEach turn: action, buy, clean up, draw five.\n- Treasures buy cards; kingdom cards change the rules\n- The game ends when the province pile or three other piles run out\n- Count victory points: provinces 6, duchies 3, estates 1, curses -1\n- The highest total wins\n\n[tool score]\nmode: categories\ncategories: provinces=6, duchies=3, estates=1, curses=-1\nwin: highest\n\n[tool turns]\nphases: Action, Buy, Cleanup\n" },
  { id: "escape-room", text: "# escape-room.gamebuddy — phases, script and one big clock\n\n[game]\nname: Escape Room\nplayers: 2-6\ntime: 60m\ntags: party, timed\nicon: escape\nsource: Generic escape-room kit\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Read the introduction out loud\n- Hide the clue envelopes before anyone enters\n- Start the main clock only when the door closes\n\n[rules]\nSolve the chain of puzzles before the clock runs out.\n- The script walks the host through the introduction and each reveal\n- Hints cost time on the main clock if you play that way\n- Solving the final puzzle stops the clock\n\n[tool timer room]\nmode: sequence\nphases: Intro=5m, Main=45m, Finale=5m\nsound: gong\nwarn-at: 5m\n\n[script story]\n1. note: Welcome the players and lock the door.\n2. say: The room is silent except for a clock. Find out why you are here.\n3. timer: room start\n4. wait: 5s\n5. say: Every envelope holds one clue. Read them in order.\n6. note: Hand out the first envelope now.\n7. wait: 30s\n8. say: If you are stuck, ask for a hint. It costs five minutes.\n9. timer: room start\n\n[tool rules]\nquick: Solve the puzzle chain before the clock runs out.\n" },
  { id: "exploding-kittens", text: "# exploding-kittens.gamebuddy — draw, defuse, survive\n\n[game]\nname: Exploding Kittens\nplayers: 2-5\ntime: 15m\ntags: cards, party\nicon: kitten\nsource: https://boardgamegeek.com/boardgame/172225/exploding-kittens\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle the deck and deal five cards each, hidden\n- Agree the number of defuse cards in play\n- The youngest player starts\n\n[rules]\nTake turns drawing cards. Draw an exploding kitten and you are out, unless you defuse it.\n- Play any number of cards, then draw one\n- Defuse, then put the kitten back anywhere in the deck\n- Survive to the end to win\n\n[tool decks deck]\ndeck: standard\ndecks: 1\njokers: 2\nplayers: 4\ndeal: 5\nhidden: yes\n\n[tool score]\nmode: simple\nwin: highest\n\n[tool rules]\nquick: Do not draw the kitten.\n" },
  { id: "gloomhaven", text: "# gloomhaven.gamebuddy — initiative, hit points and loot\n\n[game]\nname: Gloomhaven\nicon: gloomhaven\nplayers: 1-4\ntime: 90m\ntags: rpg, campaign\nsource: https://cephalofair.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Pick a scenario and lay out the map tiles\n- Place monsters and treasure as the scenario says\n- Choose two ability cards per character\n- Shuffle the monster ability deck\n\n[rules]\nA scenario is a series of rounds. Everyone picks two cards, then acts in initiative order.\n- Track hit points with the lives tool\n- Gold and experience go in the ledger as they are earned\n- A short rest or long rest costs a turn\n- Complete the scenario goal to win\n\n[tool lives]\nmode: players\nlives: 10\nmax: 30\nelimination: yes\n\n[tool score]\nmode: ledger\n\n[tool turns]\nphases: Initiative, Player, Monster, End\n" },
  { id: "hanabi", text: "# hanabi.gamebuddy — a cooperative fireworks show\n\n[game]\nname: Hanabi\nicon: hanabi\nplayers: 2-5\ntime: 25m\ntags: card, cooperative\nsource: https://boardgamegeek.com/boardgame/98778/hanabi\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle the fireworks deck and deal four or five cards to each player\n- Hold your cards facing the other players\n- Put the fuse and information tokens in the middle\n\n[rules]\nBuild five fireworks from one to five without seeing your own cards.\n- A turn is one action: play a card, discard a card or give a clue\n- Clues cost information tokens; discards refill them\n- Three fuses end the game\n- Score the highest card in each completed firework; 25 is perfect\n\n[tool score]\nmode: simple\ntarget: 25\nwin: highest\n\n[tool timer]\nmode: up\nsound: none\n" },
  { id: "just-one", text: "# just-one.gamebuddy — one word clues, one guesser\n\n[game]\nname: Just One\nicon: just-one\nplayers: 3-7\ntime: 20m\ntags: party, words\nsource: https://boardgamegeek.com/boardgame/254640/just-one\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Write a stack of mystery words, or use the word tool to draw them\n- Everyone gets a pen and a clue card\n- Choose the first guesser\n\n[rules]\nEveryone writes a one-word clue for the same mystery word.\n- Compare clues out loud; identical clues are cancelled before the guesser sees them\n- The guesser gets one guess\n- A correct guess scores one point, a wrong one scores nothing\n- Pass the role of guesser clockwise\n\n[tool words mystery]\nprofile: en\nmode: filters\n\n[tool score]\nmode: rounds\nrounds: 13\nwin: highest\n\n[tool timer turn]\nmode: countdown\nduration: 60s\nwarn-at: 15s\n" },
  { id: "kitchen-rush-timers", text: "# kitchen-rush-timers.gamebuddy — one hourglass per cook\n\n[game]\nname: Kitchen Rush\nicon: kitchen-rush\nplayers: 2-4\ntime: 45m\ntags: board, realtime\nsource: https://boardgamegeek.com/boardgame/224783/kitchen-rush\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Give every player an hourglass timer\n- Shuffle the order deck and deal the opening orders\n- Put the ingredients within reach of the whole table\n- Start the shift together\n\n[rules]\nA realtime cooperative kitchen. Your hourglass is your worker.\n- Flip your timer to take actions while it runs\n- When it empties, you must stop and wait for someone to flip it again\n- Complete orders before the shift ends\n- Track coins and wasted ingredients in the counters tool\n\n[tool timer]\nmode: flip\nduration: 90s\nper-player: yes\nplayers: 4\nlayout: grid\nsound: bell\nhaptic: short\n\n[tool counters]\ncounters: coins=0, wasted=0\nbank: 0\n" },
  { id: "love-letter", text: "# love-letter.gamebuddy — tokens of affection, one card in hand\n\n[game]\nname: Love Letter\nicon: love-letter\nplayers: 2-4\ntime: 20m\ntags: card, deduction\nsource: https://www.zmangames.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle the sixteen card deck and remove one card face down\n- Deal one card to each player\n- Put the remaining cards face down as the draw pile\n- Give the first player the tokens of affection\n\n[rules]\nDraw one card, play one card, knock players out until one is left.\n- Each card has a number and an effect; guards guess a card\n- The last player in the round wins a token of affection\n- Play until someone has four tokens\n- Add a point per round win here\n\n[tool score]\nmode: simple\ntarget: 4\nwin: highest\n" },
  { id: "mario-kart-night", text: "# mario-kart-night.gamebuddy — four races, one cup\n\n[game]\nname: Mario Kart Night\nplayers: 2-8\ntime: 60m\ntags: video-game, tournament\nicon: wheel\nsource: Fan-made helper; Mario Kart is a trademark of Nintendo\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Agree the number of races and the points for each finishing place\n- Draw the cup with the bracket tool, or skip it for a simple points night\n- Set up controllers and pick the first track\n\n[rules]\nScore points each race and crown a cup winner.\n- Write each player's points per race in the score sheet\n- Optional cup: a single-elimination bracket for a knockout evening\n- Highest total after the last race wins\n\n[tool score cup]\nmode: rounds\nrounds: 4\nwin: highest\nhint: 40 points usually wins a four-race cup\n\n[tool bracket knockout]\nformat: single\nbest-of: 1\nseeding: random\n\n[tool rules]\nquick: Most points after four races wins the cup.\n" },
  { id: "monopoly", text: "# monopoly.gamebuddy — cash on the ledger, pieces in the bank\n\n[game]\nname: Monopoly\nplayers: 2-6\ntime: 120m\ntags: board, family\nicon: monopoly\nsource: https://www.hasbro.com/en-us/product/monopoly\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Give every player 1500 in cash\n- Shuffle the chance and community chest decks\n- Put the houses and hotels in the bank\n- Each player picks a token and starts on go\n\n[rules]\nBuy, trade and charge rent until one player is left solvent.\n- Every player starts at 1500; add salary and rent, subtract purchases and fines\n- The houses and hotels counter tracks what is left in the bank\n- Highest cash is a useful tie-breaker if you stop early\n\n[tool score]\nmode: ledger\nstart: 1500\nwin: highest\n\n[tool counters]\ncounters: houses=32, hotels=12\nbank: 0\n\n[tool turns]\nphases: Roll, Buy, Build, End\n" },
  { id: "mtg", text: "# mtg.gamebuddy — twenty life, poison and commander damage\n\n[game]\nname: Magic: the Gathering\nicon: mtg\nplayers: 2-4\ntime: 30m\ntags: card, duel\nsource: https://magic.wizards.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle your decks and draw seven cards\n- Start at 20 life, or 40 in Commander\n- Agree on mulligans and who plays first\n- Keep a turn timer if the table tends to stall\n\n[rules]\nCast spells, summon creatures and reduce your opponents to zero life.\n- Life goes down and up; use the lives tool\n- Poison counters and commander damage are tracked separately\n- A player with ten poison counters loses\n- Last player standing wins\n\n[tool lives]\nmode: players\nlives: 20\nmax: 40\nelimination: yes\n\n[tool counters]\ncounters: poison=0, commander=0, treasures=0\nbank: 0\n\n[tool timer]\nmode: countdown\nduration: 2m\nsound: bell\nstart: manual\n" },
  { id: "pandemic", text: "# pandemic.gamebuddy — cubes, outbreaks and a ticking clock\n\n[game]\nname: Pandemic\nicon: pandemic\nplayers: 2-4\ntime: 45m\ntags: board, cooperative\nsource: https://www.zmangames.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Give every player a role card and a pawn\n- Place three cubes of each colour on the starting cities\n- Shuffle the infection deck and infect nine cities\n- Put the outbreak and cure markers within reach\n\n[rules]\nA cooperative race to cure four diseases before the world runs out of time.\n- Each turn: four actions, then draw cards, then infect cities\n- The infection rate rises with every outbreak\n- Five outbreaks or running out of cubes loses the game\n- Track the cube supply and outbreaks here; cure all four to win\n\n[tool counters]\ncounters: red=24, yellow=24, blue=24, black=24, outbreaks=0\nbank: 0\n\n[tool timer]\nmode: up\nsound: none\n" },
  { id: "perudo", text: "# perudo.gamebuddy — dice under cups and escalating bids\n\n[game]\nname: Perudo / Liar's Dice\nicon: perudo\nplayers: 2-6\ntime: 30m\ntags: dice, bluffing\nsource: https://boardgamegeek.com/boardgame/45/perudo\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Give every player a cup and five dice\n- Agree on the starting player\n- Everyone rolls and peeks under their own cup\n\n[rules]\nBid on how many dice of a face are on the table, then call the bluff.\n- A bid is a quantity and a face; each bid must raise the last\n- Calling a bid reveals every cup; the loser loses a die\n- Ones are wild unless someone has bid them\n- Last player with dice wins; use lives and blind bids here\n\n[tool dice]\nroll: 1d6\npool: 5d6\nmacros: cup=5d6\n\n[tool lives]\nmode: players\nlives: 5\nmax: 5\nelimination: yes\n\n[tool reveal]\nmode: bid\nmin-bid: 1\nmax-bid: 30\n" },
  { id: "phase-10", text: "# phase-10.gamebuddy — ten phases, lowest score wins\n\n[game]\nname: Phase 10\nicon: phase-10\nplayers: 2-6\ntime: 45m\ntags: card, family\nsource: https://www.mattelgames.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle the deck and deal ten cards to each player\n- Turn one card face up for the discard pile\n- Put the phase cards where everyone can see the ten goals\n\n[rules]\nEach round has one phase to complete, from two sets of three up to a run of nine.\n- Complete your phase, then go out by discarding your last card\n- Cards left in hand count against you\n- Penalty points go in the next round cell\n- The lowest total after ten rounds wins\n\n[tool score]\nmode: rounds\nrounds: 10\nwin: lowest\nstep: 5\n" },
  { id: "poker-night", text: "# poker-night.gamebuddy — stacks, a pot and blind levels\n\n[game]\nname: Poker Night\nplayers: 2-9\ntime: 180m\ntags: card, betting\nicon: poker\nsource: Traditional game — no official source\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Agree on a buy-in and give everyone the same starting stack\n- Put the chip bank in the middle\n- Set the blind level timer\n- Deal for the button\n\n[rules]\nTexas Hold'em: two hole cards, five community cards, best hand wins the pot.\n- Track each stack with a ledger entry; start everyone at the same number\n- The shared bank holds the pot and the chips not in play\n- Blind levels go up on the interval timer\n- Blind bids record secret all-in amounts\n\n[tool score]\nmode: ledger\nstart: 1000\nwin: highest\n\n[tool counters]\ncounters: pot=0\nbank: 1000\ndenominations: 1, 5, 25, 100\n\n[tool turns]\nphases: Preflop, Flop, Turn, River, Showdown\n\n[tool reveal]\nmode: bid\nmin-bid: 0\nmax-bid: 10000\n\n[tool timer]\nmode: interval\ninterval: 15m\nsound: bell\n" },
  { id: "risk", text: "# risk.gamebuddy — reinforcements, attacks and fortifying\n\n[game]\nname: Risk\nicon: risk\nplayers: 2-6\ntime: 120m\ntags: board, war\nsource: https://www.hasbro.com/en-us/product/risk\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Deal out the territory cards and place one army on each\n- Players take turns placing their remaining armies\n- Shuffle the territory deck and deal a starting hand\n\n[rules]\nTake over the world one territory at a time.\n- Reinforce from your territories and continent bonuses\n- Attack with up to three dice against up to two defenders\n- Fortify once at the end of your turn\n- Track each player's army count as a ledger entry; the last player standing wins\n\n[tool score]\nmode: ledger\n\n[tool counters]\ncounters: reinforcements=0\nbank: 0\n\n[tool turns]\nphases: Reinforce, Attack, Fortify\n\n[tool dice]\nroll: 3d6\nmacros: attacker=3d6, defender=2d6\n" },
  { id: "scrabble", text: "# scrabble.gamebuddy — draw tiles, check words, keep the score\n\n[game]\nname: Scrabble\nplayers: 2-4\ntime: 60m\ntags: words, board\nicon: scrabble\nsource: https://en.wikipedia.org/wiki/Scrabble\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Put every tile in the bag and mix them\n- Each player draws seven tiles\n- Place the board between you and agree on the dictionary\n- The player who can form a word from their tiles starts\n\n[rules]\nBuild words across the board; every letter has a value and premium squares multiply it.\n- Draw back up to seven tiles after your turn\n- Challenge a word if you think it is not allowed; the checking tool is a hint, not a referee\n- The game ends when the bag is empty and one player uses their last tile\n- Highest total wins\n\n[tool bag tiles]\nset: scrabble\ndraw: 7\ntray: per-player\n\n[tool words check]\nprofile: en\nmode: check\n\n[tool score]\nmode: simple\nwin: highest\n" },
  { id: "seven-wonders", text: "# seven-wonders.gamebuddy — seven kinds of points\n\n[game]\nname: 7 Wonders\nicon: seven-wonders\nplayers: 3-7\ntime: 45m\ntags: board, strategy\nsource: https://www.rprod.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Deal a wonder board and three coins to each player\n- Shuffle the three age decks separately\n- Put the military conflict tokens within reach\n\n[rules]\nThree ages of card drafting. Every card is played, sold or used to build a wonder.\n- Military wins beat neighbours\n- Science sets score by their combinations\n- Coins, civilian buildings, commerce and guilds all add points\n- Add up everything at the end; the highest total wins\n\n[tool score]\nmode: ledger\nwin: highest\n" },
  { id: "skull", text: "# skull.gamebuddy — place a rose, make a bid, flip the skulls\n\n[game]\nname: Skull\nicon: skull\nplayers: 3-6\ntime: 20m\ntags: party, bluffing\nsource: https://boardgamegeek.com/boardgame/92415/skull\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Give every player one mat and four discs: three roses and one skull\n- Agree on a starting player\n- Keep the discs hidden from the other players\n\n[rules]\nTwo phases: place discs face down, then bid on how many you can flip.\n- The highest bidder flips that many discs, starting with their own\n- One skull ends the attempt and costs a disc\n- Two successful bids win the game\n- Use the blind bid tool for the bidding and the scorepad for wins\n\n[tool reveal]\nmode: bid\nmin-bid: 1\nmax-bid: 8\n\n[tool score]\nmode: simple\ntarget: 2\nwin: highest\n" },
  { id: "smash-night", text: "# smash-night.gamebuddy — brackets, stocks and a shot clock\n\n[game]\nname: Smash Night\nicon: smash-night\nplayers: 2-8\ntime: 60m\ntags: video-game, tournament\nsource: Fan-made helper; Super Smash Bros. is a trademark of Nintendo\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Enter every player into the bracket\n- Agree the stock count and the stage list\n- Put the bracket on the display screen if you have a second one\n\n[rules]\nA knockout bracket of one-on-one matches.\n- Report the winner of each match in the bracket\n- Keep the agreed stocks per match\n- The bracket advances itself; use \"next up\" to call the players\n- The last player standing wins the night\n\n[tool bracket bracket]\nformat: single\nbest-of: 3\nseeding: random\n\n[tool timer match]\nmode: countdown\nduration: 8m\nwarn-at: 1m\nsound: gong\n\n[tool score standings]\nmode: simple\nwin: highest\n\n[tool rules]\nquick: Win your match, advance, repeat.\n" },
  { id: "speedrun-practice", text: "# speedrun-practice.gamebuddy — segment times against your best\n\n[game]\nname: Speedrun Practice\nplayers: 1\ntime: 30m\ntags: video-game, speedrun\nicon: speedrun\nsource: Generic practice route\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[rules]\nTime each segment of a route and compare against your personal best.\n- Space starts and splits, R resets the attempt\n- Targets are your comparison until a run beats them\n- Gold splits remember your fastest segment ever\n\n[tool splits run]\ngame: Practice Route\ncategory: Any%\nsplits: Opening | 45, Middle | 90, Boss | 60, Finale | 30\nkeys: yes\n" },
  { id: "splendor", text: "# splendor.gamebuddy — gems, cards and fifteen points\n\n[game]\nname: Splendor\nplayers: 2-4\ntime: 30m\ntags: board, engine\nicon: gem\nsource: https://www.spacecowboys.fr/splendor\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle the three development decks and lay out four of each\n- Give every player a starting tile\n- Sort the gem tokens by colour\n- Reveal five nobles\n\n[rules]\nCollect gems, buy development cards and attract nobles.\n- A turn is one action: take gems, reserve a card or buy a card\n- Cards give permanent discounts and points\n- Nobles visit at fifteen points of card bonuses\n- First to fifteen points wins; the gem counters track the bank\n\n[tool score]\nmode: simple\ntarget: 15\nwin: highest\n\n[tool counters]\ncounters: emerald=7, sapphire=7, ruby=7, diamond=7, onyx=7, gold=5\nbank: 0\n" },
  { id: "sushi-go", text: "# sushi-go.gamebuddy — three quick rounds of card picking\n\n[game]\nname: Sushi Go!\nplayers: 2-5\ntime: 20m\ntags: card, party\nicon: sushi\nsource: https://gamewright.com/product/Sushi-Go\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle the deck and deal the right number of cards per player\n- Agree on who starts the first pass\n- Keep the pudding cards visible; they score at the end\n\n[rules]\nPick one card, pass the rest, repeat. Three rounds in total.\n- Maki rolls, tempura, sashimi and dumplings score in their own ways\n- Pudding is scored after the last round\n- Add each round here; the highest total wins\n\n[tool score]\nmode: rounds\nrounds: 3\nwin: highest\n" },
  { id: "the-mind", text: "# the-mind.gamebuddy — play the cards in order without talking\n\n[game]\nname: The Mind\nicon: the-mind\nplayers: 2-4\ntime: 20m\ntags: party, cooperative\nsource: https://www.pandasaurusgames.com/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle the deck of 1 to 100 cards\n- Deal one card per player for level one\n- Put the lives and throwing stars in the middle\n- Agree that nobody may talk about their cards\n\n[rules]\nEveryone holds numbered cards. Play them in ascending order without speaking.\n- Any card played out of order costs a life\n- Clear the level and deal one more card per player\n- A throwing star lets the table discard the lowest card\n- Lose all lives and the run ends; track them here\n\n[tool lives]\nmode: shared\nlives: 3\nmax: 5\nstep: 1\nelimination: yes\n\n[tool counters]\ncounters: shurikens=1\nbank: 0\n" },
  { id: "ticket-to-ride", text: "# ticket-to-ride.gamebuddy — routes, tickets and the longest path\n\n[game]\nname: Ticket to Ride\nplayers: 2-5\ntime: 60m\ntags: board, strategy\nicon: train\nsource: https://www.daysofwonder.com/tickettoride/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Give every player 45 trains and a matching score marker\n- Deal three destination tickets and keep at least two\n- Shuffle the train deck and deal five cards to each player\n- Lay out the five face-up cards\n\n[rules]\nClaim routes by spending matching train cards, then score at the end.\n- A route is worth its printed points\n- Destination tickets add or subtract their value if completed\n- The longest continuous path is worth 10 bonus points\n- The highest total wins\n\n[tool score]\nmode: ledger\nwin: highest\n\n[tool turns]\nphases: Draw, Play, End\ntimer: 0s\npass: no\n" },
  { id: "trivia-night", text: "# trivia-night.gamebuddy — buzzers, a shot clock and a scorepad\n\n[game]\nname: Trivia Night\nplayers: 2-20\ntime: 60m\ntags: party, quiz\nicon: trivia\nsource: Generic pub-quiz format\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Pick a quizmaster who does not score\n- Split the room into teams and enter them in the score sheet\n- Arm the buzzers and agree the points per round\n\n[rules]\nAsk a question, let the first buzz answer, and score each round.\n- Arm the buzzers before reading the question; a false start hands the question over\n- One point for a correct answer, bonus points for a themed round\n- The team with the most points after the last round wins\n\n[tool buzzer buzz]\nplayers: 4\ndelay: 3s\nfalse-start: yes\n\n[tool timer shot]\nmode: countdown\nduration: 30s\nwarn-at: 10s\nsound: buzzer\n\n[tool score teams]\nmode: rounds\nrounds: 6\nwin: highest\n\n[tool prompts questions]\npacks: would-you-rather, charades\ndraw: 1\n\n[tool rules]\nquick: Most points after six rounds wins.\n" },
  { id: "uno", text: "# uno.gamebuddy — a digital deck when the real one went missing\n\n[game]\nname: Uno\nplayers: 2-10\ntime: 30m\ntags: cards, family\nicon: uno\nsource: https://en.wikipedia.org/wiki/Uno_(card_game)\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle the deck and deal seven cards each, hidden\n- Turn one card to start the discard pile\n- Agree whether stacking draw cards is allowed\n\n[rules]\nMatch the top card by colour or number, and empty your hand first.\n- Play one card, then draw if you cannot\n- Skip, reverse and draw cards do what they say\n- Call a colour when you play a wild card\n- The first player with no cards left wins the round\n\n[tool decks cards]\ndeck: uno\ndecks: 1\nplayers: 4\ndeal: 7\nhidden: yes\n\n[tool score]\nmode: rounds\nrounds: 5\nwin: lowest\n\n[tool rules]\nquick: Empty your hand first.\n" },
  { id: "werewolf", text: "# werewolf.gamebuddy — deal roles, then run the night\n\n[game]\nname: Werewolf\nplayers: 5-10\ntime: 30m\ntags: party, social-deduction\nicon: werewolf\nsource: https://boardgamegeek.com/boardgame/147949/one-night-ultimate-werewolf\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Deal one role per player, face down\n- Put the night script within reach of the narrator\n- Agree the length of the discussion phase\n\n[rules]\nVillagers must find the werewolves before the village empties.\n- Everyone looks at their role privately\n- Follow the night script: werewolves wake, the seer inspects, everyone wakes\n- Discuss for the agreed time, then vote; the most votes is out\n- The village wins when every werewolf is out; the werewolves win otherwise\n\n[tool reveal roles]\nmode: roles\nroles: werewolf=2, seer=1, troublemaker=1, villager=fill\nauto-hide: 8\n\n[tool timer discuss]\nmode: countdown\nduration: 3m\nwarn-at: 30s\nsound: bell\n\n[script night]\n1. say: Everyone, look at your role and keep it secret.\n2. reveal: roles\n3. say: Everyone, close your eyes.\n4. wait: 3s\n5. say: Werewolves, open your eyes and look at each other.\n6. wait: 5s\n7. say: Werewolves, close your eyes.\n8. say: Seer, take the phone and inspect one player's role.\n9. say: Seer, open the Reveal tool and inspect one player, then cover it again.\n10. say: Seer, close your eyes. Everyone, open your eyes.\n11. wait: 5s\n12. say: Discuss and vote for a werewolf.\n13. timer: discuss start\n\n[tool rules]\nquick: Find the werewolves before the village is destroyed.\n" },
  { id: "wingspan", text: "# wingspan.gamebuddy — birds, bonuses and round goals\n\n[game]\nname: Wingspan\nplayers: 1-5\ntime: 70m\ntags: board, engine\nicon: bird\nsource: https://stonemaiergames.com/games/wingspan/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Give every player a player mat, eight action cubes and five food\n- Deal five bird cards and keep any you can afford\n- Shuffle the bird deck and lay out the tray\n- Reveal the first round goal\n\n[rules]\nBuild an engine of birds across four rounds. Each turn is one action: play a bird, gain food, lay eggs or draw cards.\n- Birds score their printed points\n- Bonus cards and round goals add points\n- Eggs, cached food and tucked cards score at the end\n- The highest total after round four wins\n\n[tool score]\nmode: ledger\nwin: highest\n" },
  { id: "yahtzee", text: "# yahtzee.gamebuddy — thirteen categories and five dice\n\n[game]\nname: Yahtzee\nplayers: 2-6\ntime: 30m\ntags: dice, score\nicon: yahtzee\nsource: https://www.hasbro.com/en-us/product/yahtzee\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Give every player a score sheet and a pen\n- Put five dice and the cup in the middle\n- Agree on the order of play\n\n[rules]\nRoll up to three times, keeping any dice, then score one empty category.\n- Upper section counts the matching faces; 63 or more is a 35 point bonus\n- Lower section has three and four of a kind, full house, small and large straight, Yahtzee and chance\n- The highest total after thirteen rounds wins\n\n[tool dice]\nroll: 5d6\n\n[tool score]\nmode: rounds\nrounds: 13\nwin: highest\n" },
  { id: "bidding-blocks", text: "# bidding-blocks.gamebuddy — bid between cards, then play out the challenges\n\n[game]\nname: Bidding Blocks\nplayers: 3-6\ntime: 30m\ntags: pandaqi, card, trick-taking\nicon: bidding-blocks\nsource: https://pandaqi.com/bidding-blocks/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Grab a pen and paper for the score\n- Shuffle all cards into a single deck and pick the first dealer\n- Plan for eight cards each; cards are dealt one at a time, with a chance to bid after every card\n- Agree the target; the rulebook recommends 100 points\n\n[rules]\nPlay out challenges to build a house together, but an early bid can bring it down.\n- The dealer gives everyone one card, then anyone may bid on how many challenges they will win\n- Write the bid and how many cards you held when you made it; a bid can't be changed\n- Deal on until everyone has eight cards; the first bid was made with the least information and is divided by the smallest number\n- The dealer starts each challenge, either together (everyone plays facedown, highest number of the dealer's type wins) or in turn (cards must fit on top, last card wins)\n- An exact bid is worth 100 points, one off is worth 50, anything else 0, all divided by the cards you held when bidding and rounded\n- The rulebook recommends 100 points for the evening; the first player to reach it wins\n\n[tool score]\nmode: rounds\nwin: highest\ntarget: 100\nhint: 100 for an exact bid, 50 if off by one, divided by the cards you held when you bid\n" },
  { id: "captain-flip", text: "# captain-flip.gamebuddy — one flip, one action, one score pile\n\n[game]\nname: Captain Flip\nplayers: 2-6\ntime: 30m\ntags: pandaqi, tile, memory\nicon: captain-flip\nsource: https://pandaqi.com/captain-flip/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle the tile deck and lay a 5x5 grid facedown\n- Turn the two main diagonals faceup\n- For an easier game, use a 4x4 grid\n- Keep the deck and a score pile within reach\n\n[rules]\nFlip one tile on your turn and use the action on the side you turned up.\n- A heart action triggers when a tile turns faceup; a skull action when it turns facedown\n- Score a facedown tile by taking it to your score pile, then refill the gap faceup\n- You cannot score the tile you just flipped unless an action says so\n- A fully faceup row or column clears and refills with facedown tiles\n- The game ends when the map is empty; add the values of the tiles you scored\n- Highest score wins\n- The rulebook's expansions add colour patterns, negative types and a three-tile hand\n\n[tool score]\nmode: simple\nwin: highest\nhint: Add the value of every tile in your score pile\n" },
  { id: "chiptales", text: "# chiptales.gamebuddy — poker patterns without the poker table\n\n[game]\nname: Chiptales\nplayers: 2-9\ntime: 30m\ntags: pandaqi, card, betting\nicon: chiptales\nsource: https://pandaqi.com/chiptales/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Pick one game from the series and print its cards; Noble Flood also needs its contracts, Six of Sparrows its bid cards\n- Shuffle and deal the opening hands, and keep a pen and paper for the score\n- Put the draw pile and any shared row of cards where everyone can reach them\n- Read that game's rulebook; the three games score differently\n\n[rules]\nThree poker-inspired card games; each keeps the patterns and drops a different part of poker.\n- Six of Sparrows (2-5): bid on a pattern while the cards are still arriving; an exact pattern scores its value divided by the cards you held, a miss costs 10 points\n- Noble Flood (2-6): pick contracts, build a shared 5x5 map and complete their patterns; met contracts score plus, missed ones minus\n- Pietenpoker (3-9): a simpler Sinterklaas poker with two combinations, same suit or same number; the Dutch rulebook has the full rules\n- Six of Sparrows plays to a recommended 500 points\n- Noble Flood ends when the contract deck runs out; Pietenpoker ends when the deck can no longer deal a round\n- In every game the highest total wins\n\n[tool score]\nmode: rounds\nwin: highest\nhint: 500 for Six of Sparrows; the other two end when their deck runs out\n" },
  { id: "death-by-digits", text: "# death-by-digits.gamebuddy — find the numbers nobody is holding\n\n[game]\nname: Death by Digits\nplayers: 2-6\ntime: 30m\ntags: pandaqi, card, deduction\nicon: death-by-digits\nsource: https://pandaqi.com/death-by-digits/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Count the players and multiply by 3; use cards 1 to that number, three of each\n- Deal each player twice as many cards as there are players\n- Put 3 cards facedown to one side: these are the Murder\n- Leave the rest facedown as shared Evidence\n\n[rules]\nBe a math detective and name the three numbers that are in nobody's hand.\n- On your turn, either guess another player's highest or lowest card, or play a combo to the Evidence\n- A single card steals 3 random cards unless someone shows the same number to stop it\n- Two cards that add or subtract to the Midnumber (half the top number, rounded) take 2 from the Evidence\n- Three of a kind lets you look at one Murder card\n- At the end of your turn you may name the three Murder numbers; a correct answer wins at once, a wrong one puts you out\n- The base game is kid-friendly; Dastardly Digits adds six special cards\n- The game's page has the full rulebook\n" },
  { id: "feed-the-beast", text: "# feed-the-beast.gamebuddy — empty your food storage first\n\n[game]\nname: Feed the Beast\nplayers: 2-6\ntime: 30m\ntags: pandaqi, board, family\nicon: feed-the-beast\nsource: https://pandaqi.com/feed-the-beast/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Pick a beast and place it faceup in the centre; start with a level 1 beast\n- Shuffle the Tier 1 food (one dot on each side) and deal 10 to each player\n- Shuffle the menu cards, place one next to the beast, and lay 4 more faceup as the market\n- Put the rest of the food supply within reach\n\n[rules]\nKeep the beast satisfied with apples, pie and bread, and be the first to empty your food storage.\n- On your turn, place one food token on the beast\n- If it is part of the menu, take the reward or upgrade one of your food tokens\n- If it is not, you paid the wrong food: downgrade one food and draw a new Tier 1 food\n- A higher tier can stand in for any lower tier\n- At 10 food on the beast, it resets: swap in a new menu from the market and clear the food\n- If you end your turn with no food, you win at once\n- The game's page has the rulebook and every beast\n" },
  { id: "fiddlefoo", text: "# fiddlefoo.gamebuddy — open a range, let the others throw their music in\n\n[game]\nname: Fiddlefoo\nplayers: 2-6\ntime: 30m\ntags: pandaqi, card, family\nicon: fiddlefoo\nsource: https://pandaqi.com/fiddlefoo/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Place one random card of each colour in a 2x2 square: the start of the shared map\n- Shuffle the rest into a draw pile\n- Deal each player 8 cards\n- Agree who plays first\n\n[rules]\nEmpty your hand without letting the others throw their music at you.\n- On your turn, add one card to the map; it must connect, share a row (horizontal, vertical or diagonal) with another card of its colour, and not sit next to one of that colour\n- Each new pair sets a number range and a music-note difference\n- Everyone may then give you cards of that colour whose number is inside the range, or cards with that note difference\n- The cards you receive go into your hand; if you end your turn with none, the game ends and you win\n- At the end, the music notes left in each hand are negative points; play several games and the least negative total wins\n- This sheet counts the notes left and treats the lowest total as best\n\n[tool turns]\nphases: Play, Pairs, Throw in\n\n[tool score]\nmode: rounds\nwin: lowest\nhint: 0 (an empty hand); enter the music notes left in each hand\n" },
  { id: "firecrackers", text: "# firecrackers.gamebuddy — push your luck, then build a better deck\n\n[game]\nname: Firecrackers\nplayers: 2-10\ntime: 60m\ntags: pandaqi, card, push-your-luck, deck-building\nicon: firecrackers\nsource: https://pandaqi.com/firecrackers/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Build the deck: all black cards plus one coloured set per player\n- Give each player a starting deck of one card from each of three colours and two black cards\n- Shuffle each starting deck and place it facedown\n- Lay the remaining cards faceup in the shop, one pile per colour and one for cards without actions\n\n[rules]\nReveal cards to earn coins, stop before a colour explodes, and build a more valuable deck.\n- On your turn, reveal the top card of your deck or stop\n- Resolve any action, then add the numbers of revealed cards of the same colour\n- A colour total of 10 or more explodes and takes you out of the round\n- When you stop, every revealed card is worth 1 coin; buy cards from the shop into your discard\n- The round ends when everyone has stopped or exploded; the last player left becomes Firemaster\n- The game ends after the round in which the shop runs out\n- Add the numbers of all cards in your deck, including purchases; highest score wins\n\n[tool score]\nmode: simple\nwin: highest\nhint: Add the numbers of every card in your final deck\n" },
  { id: "hasty-accusations", text: "# hasty-accusations.gamebuddy — keep one secret suspect alive\n\n[game]\nname: Hasty Accusations\nplayers: 2-7\ntime: 30m\ntags: pandaqi, card, deduction, bluffing\nicon: hasty-accusations\nsource: https://pandaqi.com/hasty-accusations/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Pick a card set; the base set is best for a first game\n- Choose at least 5 suspects, and more suspects than players\n- Lay the suspects faceup in a row and put the loupe above the middle one\n- Deal each player one secret suspect card, then deal 4 playing cards each\n- Put 4 cards faceup beside the deck as the market\n\n[rules]\nKeep one secret suspect alive while the evidence piles around the others grow.\n- On your turn, play as many cards as you like under living suspects\n- A faceup card runs its action and moves the loupe forward; a facedown card moves it back\n- If you play nothing, discard your hand and move the loupe forward\n- When the loupe wraps around, review the largest evidence pile\n- Reveal that pile top to bottom; a murdered suspect is turned facedown, and a player whose secret suspect dies is out\n- Refill hands to 4 from the market, then refill the market\n- The last player left wins; the traitor variant lets one player win by outlasting everyone else\n- The rulebook has the full card actions and variants\n\n[tool lives]\nlives: 1\nmax: 1\nmode: players\nelimination: yes\nhidden: no\n\n[tool turns]\nphases: Play cards, Review, Refill\npass: no\n" },
  { id: "i-bid-you-not", text: "# i-bid-you-not.gamebuddy — build an offer, then auction it\n\n[game]\nname: I Bid You Not\nplayers: 3-6\ntime: 45m\ntags: pandaqi, card, bidding, numbers\nicon: i-bid-you-not\nsource: https://pandaqi.com/i-bid-you-not/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle the deck and place the top card faceup: it is the opening offer\n- Deal the remaining cards until the deck is empty\n- For a shorter game, remove the extreme numbers before shuffling\n- Put the used cards within reach: every player keeps a score pile\n\n[rules]\nTake turns building an offer of ascending cards, then auction it; whoever takes the offer keeps every card in it.\n- On your turn, add a card with a higher number than the last offer card, or declare an auction\n- An auction: everyone secretly picks one card from their hand, then all bids are revealed at once\n- Sort the bids from highest to lowest; if every bid falls inside the offer's number range, the order inverts\n- Ask in that order who wants the offer; the first player to take it adds every offer card to their score pile\n- A player who does not want it discards a random card from their score pile, then adds one card from their hand to the offer anywhere in the row\n- The last player in the order must take the offer, and so must anyone who cannot pay to skip\n- The lowest bid starts the next offer, and every other bid is discarded\n- The game ends when all players are out of cards; add up the price value of your score pile and the highest total wins\n\n[tool reveal]\nmode: bid\nmin-bid: 0\nmax-bid: 100\n\n[tool score]\nmode: ledger\nwin: highest\n\n[notes]\nAdd each offer you win as one ledger entry with the total price of its cards.\nThe bid tool covers 0 to 100: the base deck and Double Devices stay inside that, but\nthe Odd Inventions expansion adds negative numbers, which have to be noted by hand.\nExpansions also add card actions; they change no other rule.\n" },
  { id: "keebble-games", text: "# keebble-games.gamebuddy — word games on one sheet of paper\n\n[game]\nname: Keebble Games\nplayers: 2-6\ntime: 20-60m\ntags: pandaqi, word, paper\nicon: keebble-games\nsource: https://pandaqi.com/keebble-games/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Fold a blank sheet in half six times to make 64 cells, or print a generated starting board\n- Each player claims one edge cell as their letter hand and grabs a pen\n- Agree the word direction and the dictionary before the first word\n- For Domino, print the domino set; for Knickknack, bring one phone with internet\n\n[rules]\nScrabble-like word games played on one sheet of paper, with no tiles to lose.\n- Keebble: play a word on the grid using letters from your hand, following Scrabble placement\n- Vowels score 1, consonants 3, and a letter nobody else holds scores 5\n- Then call two letters; every other player takes one or draws a wall on an empty edge\n- The hand limit is 7; once 10 edge cells hold letters, only play words; the game ends when someone runs out\n- Keebble: Domino uses dominoes printed with an ambigram font, so each tile reads as several letters (2-6, 40m)\n- Keebble: Knickknack runs the board and extras in a phone app and needs internet (2-5, 60m)\n- Only base Keebble is pure paper; the other two need their own material\n- Highest score wins\n\n[tool words]\nprofile: en\nmode: check\n\n[tool score]\nmode: simple\nwin: highest\nhint: Add each word as it scores; the highest total wins\n" },
  { id: "luck-legends", text: "# luck-legends.gamebuddy — cards that behave like dice\n\n[game]\nname: The Luck Legends\nplayers: 2-8\ntime: 30m\ntags: pandaqi, dice, strategy\nicon: luck-legends\nsource: https://pandaqi.com/the-luck-legends/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Pick one game from the series and print its material\n- Read that game's own rulebook before the first roll; the seven games play differently\n- Shuffle the cards that stand in for the dice\n- Keep a pen and paper nearby only if the rulebook you chose asks for a score\n\n[rules]\nA series of games where a shuffled deck stands in for the dice.\n- A roll is a shuffle and the top card, so the deck is the die\n- You can customise a die by adding or removing cards, and choose how you draw\n- Each game has its own ending and its own win condition:\n- Champions of Chance (3-6): the first player out of cards wins\n- A Little White Die (2-6): the most cards when someone runs out, or the last player holding cards\n- Lucky Lions (3-6): the first to 10 points\n- Tossing Tiger, Rolling Dragon (2-6): the most cards when someone drops below 2\n- Folly & Fortune (2-6): the most health when every hand is empty\n- Chaos Contract (2-5): the first to 6 contracts\n- Deceptidice (2-8): the most cards left when someone is down to 3\n- The series page lists every title, its rulebook and the material\n" },
  { id: "magnetmen", text: "# magnetmen.gamebuddy — collect icons before they repel you\n\n[game]\nname: Magnetmen\nplayers: 2-4\ntime: 20m\ntags: pandaqi, paper, puzzle\nicon: magnetmen\nsource: https://pandaqi.com/magnetmen/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Print one game board per player and hand out pens\n- Each player picks one inventory at the edge of the board\n- Keep the board where everyone can reach it\n\n[rules]\nCollect Magnetmen while their growing repulsion cuts off the board around you.\n- On your turn, pick an unused square, cross it out and draw its icon in an empty inventory slot\n- The more copies you hold of an icon, the more squares around it you may not collect\n- One copy blocks horizontal neighbours; two blocks horizontal and vertical; three or more blocks all eight neighbours\n- A full inventory means no more turns\n- The game ends when nobody can move; add the values of all collected Magnetmen\n- Highest score wins\n- Advanced rules add a destroy action and stop you at four copies of one icon\n\n[tool score]\nmode: simple\nwin: highest\nhint: Add the printed value of every Magnetman you collected\n" },
  { id: "mammoth-messages", text: "# mammoth-messages.gamebuddy — two words, cave drawings, sixty seconds\n\n[game]\nname: Mammoth Messages\nplayers: 2-8\ntime: 30m\ntags: pandaqi, party, drawing, cooperative\nicon: mammoth-messages\nsource: https://pandaqi.com/mammoth-messages/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Print the word tiles, cave drawings and choice tiles\n- Draw one word tile and show its ten numbered words\n- Draw ten cave drawings and one choice tile\n- The choice tile names two words by number and colour\n- Keep the rest of the decks within reach for the next turn\n\n[rules]\nCommunicate two secret words using only cave drawings, while the table guesses.\n- The choice tile gives one number and one colour; those are your two words\n- You may reveal up to five cave drawings, in any arrangement, and may not move them once placed\n- Start the 60-second timer; no words, gestures or other hints\n- The others say and tap both words; both correct scores 10 points minus the drawings you revealed\n- A wrong guess or an expired timer scores 0 for that turn\n- Play 10 rounds and add the table's points; the group is trying for the highest shared total\n- If number and colour point to the same word, communicate that single word and win on the first matching guess\n\n[tool timer]\nmode: countdown\nduration: 60s\nstart: manual\nsound: bell\n\n[tool counters]\nmode: count\ncounters: Points=0\nstep: 1\n" },
  { id: "mapped-out", text: "# mapped-out.gamebuddy — build the map around the route you were dealt\n\n[game]\nname: Mapped Out\nplayers: 2-5\ntime: 30m\ntags: pandaqi, board, tile\nicon: mapped-out\nsource: https://pandaqi.com/mapped-out/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Deal each player 8 random movement cards, facedown in a row; nobody looks at them\n- Give each player a pawn and 5 map tiles for their hand\n- Place a random starting tile in the centre and put every pawn on it\n- Agree who plays the first tile\n\n[rules]\nDesign the treasure map so the route you were dealt is worth the most at the end.\n- On your turn, play one map tile from your hand onto the shared map\n- The tile's place action then resolves: reveal a movement card, swap one with another, or study several (yours or another player's)\n- Draw a new tile; the map phase ends when someone has revealed all eight of their movement cards, or the tiles run out\n- Then walk your row of cards left to right and find the fish type you visited most; repeat visits don't count\n- Each fish of that type scores 1 point; highest score wins\n- The game's page has the rulebook and a generator for your own material\n\n[tool score]\nmode: simple\nwin: highest\nhint: 1 point per fish of the type you visited most\n\n[tool turns]\nphases: Play tile, Place action, Draw\n" },
  { id: "maybe-games", text: "# maybe-games.gamebuddy — one proposal, everyone votes at once\n\n[game]\nname: Maybe Games\nplayers: 3-6\ntime: 30-60m\ntags: pandaqi, party, voting\nicon: maybe-games\nsource: https://pandaqi.com/maybe-games/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Pick one of the three games and print its material\n- Maybe Movies and Maybe Missions: build the vote deck (5 yes and 5 no per player), deal 10 each, and redeal a hand that is all one kind\n- Maybe Minister: deal 5 cards each and give everyone a Support card with 2 votes on it\n- Lay out that game's faceup market if it has one, and read its rulebook before the first proposal\n- Agree who proposes first\n\n[rules]\nEvery game here runs on the Maybe Mechanic: one player proposes, everyone votes yes or no at the same time, and the result pays some players and costs others.\n- Maybe Movies (3-6): pitch a film from the market; yes votes pay its budget, no votes sink it, and a successful film pays the yes voters\n- Maybe Missions (3-6): prepare a mission; the majority decides success, and every yes voter collects a card, green on success, red on failure\n- Maybe Minister (3-6): propose laws; accepted laws become scoring rules, and the first player to 25 points wins\n- Votes are secret: pick your card, then reveal together. The ballot below records the direction; the number on your card is what counts\n- Maybe Movies and Maybe Missions end when the votes run out; the highest total wins\n- The series page has every rulebook and the printable material\n\n[tool turns]\nphases: Propose, Vote, Resolve\n\n[tool reveal]\nmode: ballot\nballot: Yes or no?\noptions: Yes, No\n\n[tool score]\nmode: simple\nwin: highest\nhint: 25 for Maybe Minister; the other two end when the votes run out\n" },
  { id: "naivigation", text: "# naivigation.gamebuddy — one vehicle, everyone steering at once\n\n[game]\nname: Naivigation\nplayers: 2-10\ntime: 60m\ntags: pandaqi, party, cooperative\nicon: naivigation\nsource: https://pandaqi.com/naivigation/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Pick a vehicle; the five major games need the shared core set as well as that vehicle's material\n- Build the 5x5 map: 25 tiles including 5 collectibles and a starting tile, then put the vehicle on the start\n- Combine the default and vehicle cards, shuffle them faceup, and give everyone 3\n- Shuffle the health cards and take 5 as the health deck\n- Lay out 5 instruction tokens and pick a start player\n\n[rules]\nEveryone steers one vehicle together, and the trick is keeping it in one piece.\n- Play happens in rounds: take clockwise turns putting a vehicle card facedown under an empty instruction token\n- Then reveal the instructions left to right and move; the player who filled the first slot starts the next round\n- Visit all 5 collectibles to win; lose at once when the health deck is empty\n- Taking damage reveals the next health card, and its handicap stays in force\n- No table talk by default; the Discuss card is the way to buy some\n- The five major games share this core and change the vehicle; the two specials are standalone spin-offs\n- Track damage here; when the health deck runs out, the vehicle is lost\n\n[tool counters]\nmode: count\ncounters: damage=0\nstep: 1\n" },
  { id: "slippery-slopes", text: "# slippery-slopes.gamebuddy — describe a word with sliders and a timer\n\n[game]\nname: Slippery Slopes\nplayers: 2-10\ntime: 20m\ntags: pandaqi, party, guessing\nicon: slippery-slopes\nsource: https://pandaqi.com/slippery-slopes/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Shuffle the slider deck and draw 4 sliders in front of the start player\n- Shuffle the word deck and keep it within reach\n- Agree on 10 rounds and a 1-2 minute talking limit\n- For the competitive variant, split into two teams and alternate turns\n\n[rules]\nCommunicate a secret word using only a set of sliders, while the table guesses.\n- On your turn, first change the sliders; use a sideways facedown card to mark where your word ranks\n- Then start the timer and communicate using only the sliders; no words, gestures or other hints\n- Anyone may guess or ask questions during the turn\n- A correct guess scores 5 points; if time runs out, the turn scores 0\n- The default game is cooperative: add the table's points over 10 rounds\n- The competitive variant gives each team its own score after 10 rounds\n- Glidy Gifts actions are optional and each one reduces that word's score by 1\n\n[tool timer]\nmode: countdown\nduration: 2m\nstart: manual\nsound: bell\n\n[tool counters]\nmode: count\ncounters: Points=0\nstep: 5\ndown: 1\n" },
  { id: "the-game-of-dilemmas", text: "# the-game-of-dilemmas.gamebuddy — five rounds of controversial choices\n\n[game]\nname: The Game of Dilemmas\nplayers: 3-6\ntime: 30m\ntags: pandaqi, party, voting\nicon: the-game-of-dilemmas\nsource: https://pandaqi.com/the-game-of-dilemmas/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Sort the cards into positive and negative piles; ignore neutral cards for the base game\n- Shuffle both piles and place them facedown\n- Deal each player 4 positive and 4 negative cards\n- Put out yes and no tokens: half the number of dilemmas, rounded up, of each\n\n[rules]\nBuild the most controversial dilemma, then collect the yes votes it earns.\n- Each round, everyone secretly combines one positive and one negative card\n- Reveal all dilemmas, then everyone places yes/no tokens facedown on every dilemma\n- The dilemma with the smallest difference between yes and no is the most controversial and wins the round\n- Its creator scores one point per yes token on it; ties go to the dilemma with more no tokens\n- Everyone draws a new positive and negative card\n- The game ends after 5 rounds; highest score wins\n- Neutral cards, supervotes and co-op dilemmas are optional upgrades in the rulebook\n\n[tool score]\nmode: rounds\nrounds: 5\nwin: highest\nhint: One point per yes token on your winning dilemma\n" },
  { id: "throneless-games", text: "# throneless-games.gamebuddy — simultaneous votes and seat swaps\n\n[game]\nname: Throneless Games\nplayers: 4-10\ntime: 20-30m\ntags: pandaqi, card, hidden-roles, party\nicon: throneless-games\nsource: https://pandaqi.com/throneless-games/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Pick one of the four games: Smallseat, Queenseat, Kingseat or Kaizerseat, and print its Princes\n- Choose at least as many Princes as players; add all their cards, shuffle, and deal the deck equally\n- Put any leftover cards faceup in the Tell, and choose the Kingseat position\n- Trade two cards to the right, two to the left, then set one card aside as your secret Loyalty\n- Keep a facedown Tell for winning votes and a faceup Discard\n\n[rules]\nFour games built on one shared vote: everyone secretly backs a Prince while swapping seats to control the count.\n- Each round, first give one card to your neighbour; the direction alternates left and right\n- Then everyone secretly picks a vote card and reveals together\n- The Prince with the most votes wins the round; a tie goes to the Prince closest to the Kingseat clockwise\n- Winning cards go to the Tell; every other player either uses their card's action or swaps seats and one hand card\n- The game ends when all hands are empty; reveal the Tell and count the votes\n- The Prince with the most votes wins, and every player whose secret Loyalty matches that Prince also wins\n- Smallseat is the simplest, Queenseat adds a throne card, Kingseat is the middle game, Kaizerseat the longest\n- Each game has its own Princes and twists; read that game's rulebook\n" },
  { id: "waterfall", text: "# waterfall.gamebuddy — fall down the waterfall for gemstones\n\n[game]\nname: Waterfall\nplayers: 2-6\ntime: 30m\ntags: pandaqi, tile, push-your-luck\nicon: waterfall\nsource: https://pandaqi.com/waterfall/\nauthor: pandaqi\nlicense: CC-BY-SA-4.0\nformat: 1\n\n[setup]\n- Place one add (+) tile faceup to start the waterfall\n- Give every player 4 tiles and 1 pawn; place each pawn above the waterfall\n- Put the rest of the tiles facedown as the draw pile\n\n[rules]\nBuild the waterfall downward, then fall as far as your cards let you to collect gemstones.\n- On your turn, play any number of hand cards; their numbers sum to the spaces you may fall\n- For each space, choose down-left or down-right and execute the tile you land on\n- An empty space means you exit the waterfall and reset to the top\n- Score actions let you bank hand tiles whose gemstone matches your path\n- You may not enter an occupied tile unless both choices are blocked\n- The game ends at 20 or more waterfall tiles, or when the deck runs out\n- Add the values of your scored tiles; highest score wins\n\n[tool score]\nmode: simple\nwin: highest\nhint: Add the numbers on the tiles in your score pile\n" },
];
